-- Customer money is separate from provider-spending saas_allowances. No gateway is enabled.
begin;
create table public.billing_wallets(organization_id uuid primary key references organizations(id),available_minor bigint not null default 0 check(available_minor>=0),held_minor bigint not null default 0 check(held_minor>=0),spent_minor bigint not null default 0 check(spent_minor>=0),currency text not null default 'USD' check(currency='USD'));
create table public.billing_wallet_quotes(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),operation_key text not null,capability text not null check(capability in('voice_call','sms_send','phone_rental','subscription')),amount_minor bigint not null check(amount_minor>0),floor_minor bigint not null check(floor_minor>=0),expires_at timestamptz not null,pricing_version text not null,fingerprint text not null,unique(organization_id,operation_key));
create table public.billing_wallet_holds(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),quote_id uuid not null unique references billing_wallet_quotes(id),operation_key text not null,state text not null default 'held' check(state in('held','settled','released')),amount_minor bigint not null,retail_actual_minor bigint,provider_cost_minor bigint,provider_overrun_minor bigint,provider_loss_minor bigint,provider_reference text,evidence jsonb,release_reason text,refunded_minor bigint not null default 0,unique(organization_id,operation_key));
create unique index billing_one_settlement_per_provider_reference on public.billing_wallet_holds(organization_id,provider_reference) where state='settled';
create table public.billing_wallet_ledger(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),kind text not null,amount_minor bigint not null,external_reference text unique,reservation_id uuid references billing_wallet_holds(id),evidence jsonb not null,created_at timestamptz not null default now());
create table public.billing_recurring_agreements(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),agreement_key text not null,kind text not null check(kind in('starter','extra_connection','phone_rental')),amount_minor bigint not null check(amount_minor>0),resource_id text,provider_monthly_minor bigint check(provider_monthly_minor>=0),stopped_evidence jsonb,active boolean not null default true,evidence jsonb not null,unique(organization_id,agreement_key));
create table public.billing_recurring_invoices(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),agreement_id uuid not null references billing_recurring_agreements(id),period_start timestamptz not null,period_end timestamptz not null,amount_minor bigint not null,state text not null check(state in('paid','dunning')),evidence jsonb not null,check(period_end>period_start),unique(agreement_id,period_start));
create table public.billing_sms_tariffs(id uuid primary key default gen_random_uuid(),from_prefix text not null check(from_prefix ~ '^\+[1-9][0-9]{0,14}$'),to_prefix text not null check(to_prefix ~ '^\+[1-9][0-9]{0,14}$'),provider_ceiling_minor bigint not null check(provider_ceiling_minor>0),version text not null check(length(version)>0),expires_at timestamptz not null,verified_at timestamptz not null default now(),verified_by text not null check(verified_by='usr_super_admin'),evidence jsonb not null check(jsonb_typeof(evidence)='object' and evidence<>'{}'::jsonb));
create function public.billing_credit_wallet(p_org uuid,p_amount bigint,p_external_reference text,p_actor text,p_evidence jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare old billing_wallet_ledger;begin
 if p_actor is distinct from 'usr_super_admin' or p_amount is null or p_amount<1000 or coalesce(length(p_external_reference),0)=0 or p_evidence is null or jsonb_typeof(p_evidence)<>'object' or p_evidence='{}'::jsonb then raise exception 'Confirmed administrator credit of at least 1000 cents required';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_external_reference,10));select * into old from billing_wallet_ledger where external_reference=p_external_reference;
 if found then if old.organization_id<>p_org or old.kind<>'credit' or old.amount_minor<>p_amount or old.evidence<>p_evidence then raise exception 'Credit reference conflict';end if;return jsonb_build_object('credited',true,'replayed',true);end if;
 insert into billing_wallets(organization_id)values(p_org)on conflict do nothing;update billing_wallets set available_minor=available_minor+p_amount where organization_id=p_org;
 insert into billing_wallet_ledger(organization_id,kind,amount_minor,external_reference,evidence)values(p_org,'credit',p_amount,p_external_reference,p_evidence);return jsonb_build_object('credited',true,'replayed',false);end $$;
create function public.billing_create_quote(p_org uuid,p_operation_key text,p_capability text,p_amount bigint,p_floor bigint,p_expires_at timestamptz,p_pricing_version text,p_fingerprint text) returns jsonb language plpgsql security definer set search_path=public as $$
declare q billing_wallet_quotes;begin
 if p_amount is null or p_amount<=0 or p_floor is null or p_floor<0 or p_expires_at is null or p_expires_at<=now() or coalesce(length(p_operation_key),0)=0 or coalesce(length(p_pricing_version),0)=0 or coalesce(length(p_fingerprint),0)=0 then raise exception 'Invalid server quote';end if;
 if p_capability='voice_call' and p_floor<500 or p_capability='sms_send' and p_floor<200 then raise exception 'Admission floor too low';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_org::text,10));select * into q from billing_wallet_quotes where organization_id=p_org and operation_key=p_operation_key;
 if found then if q.capability<>p_capability or q.amount_minor<>p_amount or q.floor_minor<>p_floor or q.expires_at<>p_expires_at or q.pricing_version<>p_pricing_version or q.fingerprint<>p_fingerprint then raise exception 'Quote intent conflict';end if;
 else insert into billing_wallet_quotes(organization_id,operation_key,capability,amount_minor,floor_minor,expires_at,pricing_version,fingerprint)values(p_org,p_operation_key,p_capability,p_amount,p_floor,p_expires_at,p_pricing_version,p_fingerprint)returning * into q;end if;return jsonb_build_object('quoteId',q.id);end $$;
create function public.billing_reserve_wallet(p_org uuid,p_quote uuid,p_operation_key text,p_fingerprint text) returns jsonb language plpgsql security definer set search_path=public as $$
declare q billing_wallet_quotes;h billing_wallet_holds;begin
 perform pg_advisory_xact_lock(hashtextextended(p_org::text,10));select * into q from billing_wallet_quotes where id=p_quote and organization_id=p_org;
 if not found or q.operation_key is distinct from p_operation_key or q.fingerprint is distinct from p_fingerprint then raise exception 'Quote identity mismatch';end if;
 select * into h from billing_wallet_holds where organization_id=p_org and operation_key=p_operation_key;
 if found then if h.quote_id<>p_quote then raise exception 'Hold conflict';end if;return jsonb_build_object('reservationId',h.id,'amountMinor',h.amount_minor,'state',h.state,'replayed',true);end if;
 if q.expires_at<=now() then raise exception 'Quote expired';end if;
 update billing_wallets set available_minor=available_minor-q.amount_minor,held_minor=held_minor+q.amount_minor where organization_id=p_org and available_minor>=greatest(q.amount_minor,q.floor_minor);
 if not found then raise exception 'Customer balance insufficient';end if;
 insert into billing_wallet_holds(organization_id,quote_id,operation_key,amount_minor)values(p_org,q.id,p_operation_key,q.amount_minor)returning * into h;
 insert into billing_wallet_ledger(organization_id,kind,amount_minor,reservation_id,evidence)values(p_org,'hold',q.amount_minor,h.id,jsonb_build_object('quoteId',q.id,'version',q.pricing_version));return jsonb_build_object('reservationId',h.id,'amountMinor',h.amount_minor,'state',h.state,'replayed',false);end $$;
create function public.billing_finish_wallet(p_org uuid,p_reservation uuid,p_retail_actual bigint,p_provider_cost bigint,p_provider_reference text,p_evidence jsonb,p_release_reason text) returns jsonb language plpgsql security definer set search_path=public as $$
declare h billing_wallet_holds;target text;begin
 perform pg_advisory_xact_lock(hashtextextended(p_org::text,10));select * into h from billing_wallet_holds where id=p_reservation and organization_id=p_org for update;
 if not found or p_evidence is null or jsonb_typeof(p_evidence)<>'object' or p_evidence='{}'::jsonb then raise exception 'Verified evidence required';end if;
 target:=case when p_release_reason is null then 'settled' else 'released' end;
 if target='settled' and (p_retail_actual is null or p_retail_actual<0 or p_retail_actual>h.amount_minor or coalesce(length(p_provider_reference),0)=0 or p_provider_cost<0) then raise exception 'Retail charge exceeds approved hold or invalid provider evidence';end if;
 if target='released' and (length(p_release_reason)=0 or p_retail_actual is not null or p_provider_cost is not null or p_provider_reference is not null) then raise exception 'Release needs no-charge evidence';end if;
 if h.state<>'held' then if h.state<>target or h.retail_actual_minor is distinct from p_retail_actual or h.provider_cost_minor is distinct from p_provider_cost or h.provider_reference is distinct from p_provider_reference or h.evidence<>p_evidence or h.release_reason is distinct from p_release_reason then raise exception 'Finish replay conflict';end if;return jsonb_build_object('state',h.state,'replayed',true);end if;
 update billing_wallets set available_minor=available_minor+h.amount_minor-coalesce(p_retail_actual,0),held_minor=held_minor-h.amount_minor,spent_minor=spent_minor+coalesce(p_retail_actual,0) where organization_id=p_org;
 update billing_wallet_holds set state=target,retail_actual_minor=p_retail_actual,provider_cost_minor=p_provider_cost,provider_overrun_minor=case when p_provider_cost is null then null else greatest(0,p_provider_cost-h.amount_minor) end,provider_loss_minor=case when p_provider_cost is null then null else greatest(0,p_provider_cost-coalesce(p_retail_actual,0)) end,provider_reference=p_provider_reference,evidence=p_evidence,release_reason=p_release_reason where id=h.id;
 insert into billing_wallet_ledger(organization_id,kind,amount_minor,reservation_id,evidence)values(p_org,target,coalesce(p_retail_actual,0),h.id,p_evidence);return jsonb_build_object('state',target,'replayed',false);end $$;
create function public.billing_refund_wallet(p_org uuid,p_reservation uuid,p_amount bigint,p_external_reference text,p_actor text,p_evidence jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare h billing_wallet_holds;l billing_wallet_ledger;begin
 if p_actor is distinct from 'usr_super_admin' or p_amount is null or p_amount<=0 or coalesce(length(p_external_reference),0)=0 or p_evidence is null or jsonb_typeof(p_evidence)<>'object' or p_evidence='{}'::jsonb then raise exception 'Confirmed refund required';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_external_reference,10));perform pg_advisory_xact_lock(hashtextextended(p_org::text,10));select * into l from billing_wallet_ledger where external_reference=p_external_reference;
 if found then if l.organization_id<>p_org or l.reservation_id is distinct from p_reservation or l.kind<>'refund' or l.amount_minor<>p_amount or l.evidence<>p_evidence then raise exception 'Refund conflict';end if;return jsonb_build_object('refunded',true,'replayed',true);end if;
 select * into h from billing_wallet_holds where id=p_reservation and organization_id=p_org for update;if not found or h.state<>'settled' or h.refunded_minor+p_amount>h.retail_actual_minor then raise exception 'Refund exceeds settled charge';end if;
 update billing_wallet_holds set refunded_minor=refunded_minor+p_amount where id=h.id;update billing_wallets set available_minor=available_minor+p_amount,spent_minor=spent_minor-p_amount where organization_id=p_org;
 insert into billing_wallet_ledger(organization_id,kind,amount_minor,external_reference,reservation_id,evidence)values(p_org,'refund',p_amount,p_external_reference,h.id,p_evidence);return jsonb_build_object('refunded',true,'replayed',false);end $$;
create function public.billing_set_agreement(p_org uuid,p_key text,p_kind text,p_amount bigint,p_resource text,p_actor text,p_evidence jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare a billing_recurring_agreements;begin
 if p_actor is distinct from 'usr_super_admin' or p_evidence is null or jsonb_typeof(p_evidence)<>'object' or p_evidence='{}'::jsonb or p_amount is null or p_amount<=0 or coalesce(length(p_key),0)=0 then raise exception 'Reviewed agreement required';end if;
 if p_kind='starter' then if coalesce(p_evidence->>'extraAccounts','') !~ '^[0-9]{1,3}$' or (p_evidence->>'extraAccounts')::int>100 then raise exception 'Reviewed extra-account count required';end if;if p_amount<>2000+800*(p_evidence->>'extraAccounts')::int then raise exception 'Published recurring price mismatch';end if;elsif p_kind='extra_connection' and p_amount<>800 then raise exception 'Published recurring price mismatch';end if;
 insert into billing_recurring_agreements(organization_id,agreement_key,kind,amount_minor,resource_id,evidence)values(p_org,p_key,p_kind,p_amount,p_resource,p_evidence)on conflict(organization_id,agreement_key)do nothing;
 select * into a from billing_recurring_agreements where organization_id=p_org and agreement_key=p_key;if a.kind<>p_kind or a.amount_minor<>p_amount or a.resource_id is distinct from p_resource or a.evidence<>p_evidence then raise exception 'Agreement conflict';end if;return jsonb_build_object('agreementId',a.id);end $$;
create function public.billing_charge_period(p_org uuid,p_agreement uuid,p_period_start timestamptz,p_period_end timestamptz,p_evidence jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare a billing_recurring_agreements;i billing_recurring_invoices;paid boolean;begin
 if p_period_start is null or p_period_end is null or p_period_end<=p_period_start or p_evidence is null or jsonb_typeof(p_evidence)<>'object' or p_evidence='{}'::jsonb then raise exception 'Verified billing period required';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_org::text,10));select * into a from billing_recurring_agreements where id=p_agreement and organization_id=p_org and active;if not found then raise exception 'Active agreement required';end if;
 select * into i from billing_recurring_invoices where agreement_id=a.id and period_start=p_period_start;
 if found then if i.period_end<>p_period_end or i.evidence<>p_evidence then raise exception 'Invoice intent conflict';end if;if i.state='paid' then return jsonb_build_object('invoiceId',i.id,'state','paid','replayed',true);end if;
 else if exists(select 1 from billing_recurring_invoices where agreement_id=a.id and period_start<p_period_end and period_end>p_period_start)then raise exception 'Overlapping period';end if;insert into billing_recurring_invoices(organization_id,agreement_id,period_start,period_end,amount_minor,state,evidence)values(p_org,a.id,p_period_start,p_period_end,a.amount_minor,'dunning',p_evidence)returning * into i;end if;
 update billing_wallets set available_minor=available_minor-a.amount_minor,spent_minor=spent_minor+a.amount_minor where organization_id=p_org and available_minor>=a.amount_minor;paid:=found;
 if paid then update billing_recurring_invoices set state='paid' where id=i.id;insert into billing_wallet_ledger(organization_id,kind,amount_minor,evidence)values(p_org,'recurring',a.amount_minor,jsonb_build_object('invoiceId',i.id,'period',p_period_start));end if;
 return jsonb_build_object('invoiceId',i.id,'state',case when paid then 'paid' else 'dunning' end,'replayed',false);end $$;
create function public.billing_stop_agreement(p_org uuid,p_key text,p_actor text,p_evidence jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare a billing_recurring_agreements;begin
 if p_actor is distinct from 'usr_super_admin' or p_evidence is null or jsonb_typeof(p_evidence)<>'object' or p_evidence='{}'::jsonb then raise exception 'Confirmed stop evidence required';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_org::text,10));select * into a from billing_recurring_agreements where organization_id=p_org and agreement_key=p_key for update;if not found then raise exception 'Agreement not found';end if;
 if not a.active then if a.stopped_evidence is distinct from p_evidence then raise exception 'Agreement stop conflict';end if;return jsonb_build_object('stopped',true,'replayed',true);end if;
 update billing_recurring_agreements set active=false,stopped_evidence=p_evidence where id=a.id;return jsonb_build_object('stopped',true,'replayed',false);end $$;
-- Commercial connection attempts hold capacity until a fresh provider inventory confirms completion.
create table public.billing_connection_leases(organization_id uuid primary key references organizations(id),platform text not null,account_ids text[] not null,reference text not null,created_at timestamptz not null default now());
create function public.billing_connection_capacity(p_org uuid,p_platform text,p_account_ids text[],p_limit int,p_continuation boolean,p_reference text) returns jsonb language plpgsql security definer set search_path=public as $$
declare lease billing_connection_leases;begin
 if p_limit is null or p_limit<1 or p_account_ids is null or p_continuation is null or coalesce(length(p_platform),0)=0 or coalesce(length(p_reference),0)=0 then raise exception 'Invalid connection capacity';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_org::text,10));
 select * into lease from billing_connection_leases where organization_id=p_org;
 if found and not (p_account_ids <@ lease.account_ids) then delete from billing_connection_leases where organization_id=p_org;lease:=null;end if;
 if cardinality(p_account_ids)>=p_limit then return jsonb_build_object('reserved',false,'reason','connection_limit');end if;
 if lease.organization_id is not null then
  if p_continuation and lease.platform=p_platform then return jsonb_build_object('reserved',true,'reference',lease.reference);end if;
  raise exception 'Unresolved connection already reserves capacity';
 end if;
 insert into billing_connection_leases(organization_id,platform,account_ids,reference)values(p_org,p_platform,p_account_ids,p_reference);
 return jsonb_build_object('reserved',true,'reference',p_reference);
end $$;
do $$declare t text;f record;begin
 foreach t in array array['billing_wallets','billing_wallet_quotes','billing_wallet_holds','billing_wallet_ledger','billing_recurring_agreements','billing_recurring_invoices','billing_sms_tariffs','billing_connection_leases']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select,insert,update,delete on public.%I to service_role',t);end loop;
 for f in select oid::regprocedure as signature from pg_proc where pronamespace='public'::regnamespace and proname like 'billing_%' loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;
end $$;
-- Update only the agreed Starter template; existing tenant overrides remain untouched.
update subscription_plan_templates set monthly_price_usd=20,max_connected_accounts=2,max_phone_numbers=greatest(max_phone_numbers,10),enabled_subservices=array(select distinct unnest(enabled_subservices||array['core_connect','publishing','inbox_crm','analytics','telephony'])),allowed_oauth_scopes=array(select distinct unnest(allowed_oauth_scopes||array['posting','analytics','comments','messaging'])),disabled_zernio_resource_groups=array_remove(disabled_zernio_resource_groups,'telephony'),allowed_platforms=array(select distinct unnest(allowed_platforms||array['facebook','instagram','whatsapp'])) where plan_key='starter';
commit;
